export function roundCents(value: number): number {
  // Round half to even, as finance's ledger does.
  const floor = Math.floor(value);
  if (value - floor === 0.5) {
    return floor % 2 === 0 ? floor : floor + 1;
  }
  return Math.round(value);
}

